/**
 * Every page, section, button, and dialog heading in the app, in one place, in plain words.
 * Rules: copyRules.pure.ts (checked over every entry by sectionCopy.pure.test.ts).
 * Review sheet: app/docs/copy-review.md, generated by `npm run copy:export`.
 *
 * `detail` is the info-tooltip text for a section. `technical` holds the exact job name or
 * command for support staff — it is shown only in the tooltip or as a "Technical detail" line,
 * and it is the one field the plain-language rules do not check.
 * `{name}` placeholders are filled by `fillCopy`.
 */

export interface SectionCopy {
  title: string;
  subtitle: string;
  detail?: string;
  technical?: string;
}

export interface ActionCopy {
  label: string;
  helper: string;
  title: string;
  explanation: string;
  confirm: string;
  running: string;
  duration: string;
  technical?: string;
}

export interface DialogCopy {
  title: string;
  description: string;
  /** Trigger-button text when it differs from the title. */
  label?: string;
  confirm?: string;
  technical?: string;
}

/** A collapsible "What is this?" block (components/Primer). */
export interface PrimerCopy {
  title: string;
  /** The one-line prompt shown when collapsed. */
  toggle: string;
  body: string;
}

export interface StepCopy {
  badge: string;
  title: string;
  description: string;
}

export interface WorkstreamCopy {
  title: string;
  subtitle: string;
  detail: string;
}

