// --------------------------------------------------------------------------- helpers

/** Fill `{name}` placeholders. Throws on a missing var, so a typo never ships a raw `{name}`. */
export function fillCopy(template: string, vars: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (_, name: string) => {
    if (!(name in vars)) throw new Error(`fillCopy: missing var "${name}" for "${template}"`);
    return String(vars[name]);
  });
}

/** The page subtitle under the shell title. Null on How it works (the module hero owns it). */
export function pageIntroForPath(pathname: string): SectionCopy | null {
  if (pathname === '/how-it-works' || pathname.startsWith('/how-it-works/')) return null;
  if (pathname.startsWith('/workstreams/')) return PAGE_COPY['/workstreams/:workstream'];
  return PAGE_COPY[pathname] ?? null;
}

const OPTIONAL_STEP_KINDS = new Set(['lease', 'freeze']);

/** The line under "Your next step", by next-step kind. */
export function nextStepSubtitle(kind: string | null | undefined): string {
  const k = (kind ?? '').toLowerCase();
  if (k === 'done') return SECTION_COPY.overview.nextStepDone.subtitle;
  if (k === 'blocked') return SECTION_COPY.overview.nextStepBlocked.subtitle;
  if (OPTIONAL_STEP_KINDS.has(k)) return SECTION_COPY.overview.nextStepOptional.subtitle;
  return SECTION_COPY.overview.nextStep.subtitle;
}

/** The on-screen name of a next step. Unknown kinds keep the backend title. */
export function stepTitle(kind: string | null | undefined, fallback: string): string {
  return STEP_COPY[(kind ?? '').toLowerCase()]?.title ?? fallback;
}

/** The short badge for a next step. Unknown kinds keep the raw kind. */
export function stepBadge(kind: string | null | undefined): string {
  return STEP_COPY[(kind ?? '').toLowerCase()]?.badge ?? (kind ?? '');
}

/**
 * A dialog entry as JobTriggerDialog / ConvertGateDialog props, with `{name}` placeholders
 * filled. Spread it: `<JobTriggerDialog {...dialogProps(DIALOG_COPY.x, { scope })} … />`.
 */
export function dialogProps(
  d: DialogCopy,
  vars: Record<string, string | number> = {},
): { triggerLabel: string; title: string; description: string; confirmLabel?: string; technical?: string } {
  return {
    triggerLabel: fillCopy(d.label ?? d.title, vars),
    title: fillCopy(d.title, vars),
    description: fillCopy(d.description, vars),
    confirmLabel: d.confirm === undefined ? undefined : fillCopy(d.confirm, vars),
    technical: d.technical === undefined ? undefined : fillCopy(d.technical, vars),
  };
}

/** Which length cap a field obeys. `technical` is exempt from every rule. */
export type CopyFieldKind = 'title' | 'subtitle' | 'helper' | 'dialog' | 'primer' | 'technical';

/** One copy string, flattened for the copy test and the review sheet. */
export interface CopyEntry {
  group: string;
  key: string;
  field: string;
  kind: CopyFieldKind;
  text: string;
}

const SECTION_GROUP_LABELS: Record<string, string> = {};

function groupLabel(page: string): string {
  return SECTION_GROUP_LABELS[page] ?? page.charAt(0).toUpperCase() + page.slice(1);
}

/** Every string in this module, in review-sheet order. */
export function copyEntries(): CopyEntry[] {
  const out: CopyEntry[] = [];
  const push = (group: string, key: string, field: string, kind: CopyFieldKind, text: string | undefined) => {
    if (text !== undefined) out.push({ group, key, field, kind, text });
  };
  const pushSection = (group: string, key: string, c: SectionCopy) => {
    push(group, key, 'title', 'title', c.title);
    push(group, key, 'subtitle', 'subtitle', c.subtitle);
    push(group, key, 'detail', 'dialog', c.detail);
    push(group, key, 'technical', 'technical', c.technical);
  };
  for (const [key, c] of Object.entries(PAGE_COPY)) pushSection('Pages', key, c);
  for (const [page, sections] of Object.entries(SECTION_COPY)) {
    for (const [key, c] of Object.entries(sections as Record<string, SectionCopy>)) {
      pushSection(groupLabel(page), key, c);
    }
  }
  for (const [key, c] of Object.entries(WORKSTREAM_COPY)) {
    push('Workstreams', key, 'title', 'title', c.title);
    push('Workstreams', key, 'subtitle', 'subtitle', c.subtitle);
    push('Workstreams', key, 'detail', 'dialog', c.detail);
  }
  for (const [key, text] of Object.entries(CLUSTERING_COPY)) {
    push('Clustering step', key, 'line', 'helper', text);
  }
  for (const [key, c] of Object.entries(BLOCKER_COPY)) {
    push('Blockers', key, 'title', 'title', c.title);
    push('Blockers', key, 'fix', 'subtitle', c.fix);
  }
  for (const [key, text] of Object.entries(FOCUS_COPY)) {
    const kind: CopyFieldKind = text.includes('. ') || text.length > 40 ? 'subtitle' : 'title';
    push('Focus', key, 'label', kind, text);
  }
  for (const [key, c] of Object.entries(STEP_COPY)) {
    push('Next step', key, 'badge', 'title', c.badge);
    push('Next step', key, 'title', 'title', c.title);
    push('Next step', key, 'description', 'subtitle', c.description);
  }
  for (const [key, text] of Object.entries(VERDICT_COPY)) push('Next step', `verdict.${key}`, 'label', 'subtitle', text);
  for (const [key, c] of Object.entries(ACTION_COPY as Record<string, ActionCopy>)) {
    push('Buttons', key, 'label', 'title', c.label);
    push('Buttons', key, 'helper', 'helper', c.helper);
    push('Buttons', key, 'title', 'title', c.title);
    push('Buttons', key, 'explanation', 'dialog', c.explanation);
    push('Buttons', key, 'confirm', 'title', c.confirm);
    push('Buttons', key, 'running', 'title', c.running);
    push('Buttons', key, 'technical', 'technical', c.technical);
  }
  for (const [key, c] of Object.entries(DIALOG_COPY as Record<string, DialogCopy>)) {
    push('Dialogs', key, 'label', 'title', c.label);
    push('Dialogs', key, 'title', 'title', c.title);
    push('Dialogs', key, 'description', 'dialog', c.description);
    push('Dialogs', key, 'confirm', 'title', c.confirm);
    push('Dialogs', key, 'technical', 'technical', c.technical);
  }
  for (const [key, text] of Object.entries(LABEL_COPY as Record<string, string>)) {
    push('Buttons', key, 'label', 'title', text);
  }
  for (const [key, c] of Object.entries(PRIMER_COPY as Record<string, PrimerCopy>)) {
    push('Primers', key, 'title', 'title', c.title);
    push('Primers', key, 'toggle', 'subtitle', c.toggle);
    push('Primers', key, 'body', 'primer', c.body);
  }
  return out;
}
